        Colors[ 2] := 'EDFF11'; // Yellow
        Colors[ 3] := '0000FF'; // Blue
        Colors[ 4] := 'FF0000'; // Red
        Colors[ 5] := '1D9F00'; // DarkGreen
        Colors[ 6] := 'CA75FF'; // LightViolett
        Colors[ 7] := 'F7FF88'; // LightYellow
        Colors[ 8] := '71FFD9'; // Magenta
        Colors[ 9] := 'FF5C00'; // Orange
        Colors[10] := '87FF4A'; // LightGreen
        Colors[11] := '45575E'; // Gray

        R := 0.7;
        include 'Figures\Scripts\Dodecahedron_Coordinates.inc';

        D := R * 0.55;
        p5 := 2 * Pi/5;

        function GetInt(): integer;
        begin
          p := Pos(',', sSplits);
          if p = 0 then begin
            substr := sSplits;
            sSplits := '';
          end else begin
            substr := copy(sSplits, 1, p-1);
            Delete(sSplits, 1, p);
          end;
          Result := StrToInt(Trim(substr));
        end;

        procedure GetSplits();
        begin
          pCount := 0;
          while Length(sSplits) > 0 do begin
            Splits[pCount] := GetInt;
            Inc(pCount);
          end;
        end;

